mapper.select:
SELECT t.id, t.ticket_no, t.business_domain_id, d.code AS business_domain_code, d.name AS business_domain_name, t.ticket_type_id, tt.name AS ticket_type_name, t.customer_id, t.assigned_to, t.title, t.description, t.status, t.priority, t.source, t.result, t.version, CAST(t.custom_fields AS CHAR) AS custom_fields_json, t.sla_first_response_deadline, t.sla_resolution_deadline, t.sla_first_responded_at, t.sla_resolved_at, t.sla_status, t.sla_paused_duration, t.sla_pause_started_at, t.created_at, t.updated_at, ( SELECT MAX(r.created_at) FROM ticket_reply r WHERE r.ticket_id = t.id ) AS last_reply_at, COALESCE(( SELECT COUNT(*) FROM ticket_reply r WHERE r.ticket_id = t.id ), 0) AS reply_count FROM ticket t JOIN business_domain d ON d.id = t.business_domain_id JOIN ticket_type tt ON tt.id = t.ticket_type_id WHERE t.business_domain_id = #{domainId}
AND t.customer_id = #{customerId}
AND t.status = #{status}
ORDER BY t.updated_at DESC, t.id DESC LIMIT #{limit}

SELECT COUNT(*)
FROM ticket t
WHERE t.business_domain_id = #{domainId}

    AND t.customer_id = #{customerId}


    AND t.status = #{status}


    AND t.assignee_staff_account_id = #{assignee}


    AND t.priority = #{priority}


    AND t.title LIKE CONCAT('%', #{keyword}, '%')


    AND t.sla_status = #{slaStatus}

SELECT t.id, t.ticket_no, t.business_domain_id, d.code AS business_domain_code, d.name AS business_domain_name, t.ticket_type_id, tt.name AS ticket_type_name, t.customer_id, t.assigned_to, t.title, t.description, t.status, t.priority, t.source, t.result, t.version, CAST(t.custom_fields AS CHAR) AS custom_fields_json, t.sla_first_response_deadline, t.sla_resolution_deadline, t.sla_first_responded_at, t.sla_resolved_at, t.sla_status, t.sla_paused_duration, t.sla_pause_started_at, t.created_at, t.updated_at, ( SELECT MAX(r.created_at) FROM ticket_reply r WHERE r.ticket_id = t.id ) AS last_reply_at, COALESCE(( SELECT COUNT(*) FROM ticket_reply r WHERE r.ticket_id = t.id ), 0) AS reply_count, COALESCE(sa.nickname, sa.real_name) AS assignee_name, COALESCE(ca.nickname, ca.real_name) AS customer_name FROM ticket t JOIN business_domain d ON d.id = t.business_domain_id JOIN ticket_type tt ON tt.id = t.ticket_type_id LEFT JOIN staff_account sa ON sa.id = t.assignee_staff_account_id LEFT JOIN customer_account ca ON ca.id = t.customer_id WHERE t.business_domain_id = #{domainId}
AND t.customer_id = #{customerId}
AND t.status = #{status}
AND t.assignee_staff_account_id = #{assignee}
AND t.priority = #{priority}
AND t.title LIKE CONCAT('%', #{keyword}, '%')
AND t.sla_status = #{slaStatus}
ORDER BY t.updated_at DESC, t.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COALESCE(MAX(CAST(SUBSTRING_INDEX(ticket_no, '-', -1) AS UNSIGNED)), 0) + 1
FROM ticket
WHERE business_domain_id = #{domainId} AND ticket_no LIKE #{prefix}
